using System.Security.Cryptography; using System.Text; using System.Text.Json; using Microsoft.AspNetCore.DataProtection; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Options; using OrcaFacil.Application.Abstractions; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence; using OrcaFacil.Web.Email;
namespace OrcaFacil.Web.Security;
public interface IPasswordRecoveryService { Task RequestResetAsync(string email,string correlationId,string? remoteIp,string? userAgent,CancellationToken ct); Task<bool> IsTokenValidAsync(string token,CancellationToken ct); Task<bool> ResetAsync(string token,string newPassword,CancellationToken ct); }
public sealed record OutboxPayload(string Subject,string Text,string Html,DateTime? ExpiresAt=null);
public sealed class PasswordRecoveryService(OrcaFacilDbContext db,IPasswordResetTokenService tokens,IDataProtectionProvider protection,IOptions<PasswordResetOptions> resetOptions,IOptions<ApplicationUrlOptions> appOptions,IOptions<SecuritySecretOptions> secrets,IPasswordHasher hasher,ILogger<PasswordRecoveryService> logger):IPasswordRecoveryService
{
 const string Generic="Caso exista uma conta com esse e-mail, enviaremos as instruções para redefinir a senha.";
 public async Task RequestResetAsync(string email,string correlationId,string? remoteIp,string? userAgent,CancellationToken ct){var started=DateTime.UtcNow;var normalized=email.Trim().ToLowerInvariant();var emailHash=Hmac(normalized);logger.LogInformation("PASSWORD_RESET_REQUEST_RECEIVED CorrelationId {CorrelationId} EmailHash {EmailHash}",correlationId,emailHash);var cutoff=started.AddHours(-1);var recent=await db.PasswordResetTokens.CountAsync(x=>x.CreatedAt>=cutoff&&x.RequestedIpHash==Hmac(remoteIp??"unknown"),ct);var user=await db.Users.SingleOrDefaultAsync(x=>x.Email.ToLower()==normalized&&!x.IsDeleted,ct);if(user is null||!user.IsActive||user.IsBlocked||recent>=resetOptions.Value.MaximumRequestsPerHour){await Task.Delay(Random.Shared.Next(80,141),ct);logger.LogInformation("PASSWORD_RESET_REQUEST_ACCEPTED CorrelationId {CorrelationId} EmailHash {EmailHash} Result Generic",correlationId,emailHash);return;}var last=await db.PasswordResetTokens.Where(x=>x.UserId==user.Id).OrderByDescending(x=>x.CreatedAt).Select(x=>(DateTime?)x.CreatedAt).FirstOrDefaultAsync(ct);if(last.HasValue&&last.Value.AddSeconds(resetOptions.Value.MinimumRequestIntervalSeconds)>started){await Task.Delay(100,ct);return;}await using var tx=await db.Database.BeginTransactionAsync(ct);foreach(var old in await db.PasswordResetTokens.Where(x=>x.UserId==user.Id&&x.UsedAt==null&&x.RevokedAt==null&&x.ExpiresAt>started).ToListAsync(ct))old.Revoke(started);var raw=tokens.Generate();var entity=new PasswordResetToken{UserId=user.Id,TokenHash=tokens.Hash(raw),ExpiresAt=started.AddMinutes(resetOptions.Value.TokenLifetimeMinutes),RequestedCorrelationId=correlationId,RequestedIpHash=Hmac(remoteIp??"unknown"),UserAgentHash=Hmac(userAgent??"unknown")};db.PasswordResetTokens.Add(entity);var link=$"{appOptions.Value.PublicBaseUrl.TrimEnd('/')}/Auth/ResetPassword?token={Uri.EscapeDataString(raw)}";var payload=RecoveryTemplate(link,resetOptions.Value.TokenLifetimeMinutes,entity.ExpiresAt);var recipientProtector=protection.CreateProtector("OrcaFacil.EmailOutbox.Recipient.v1");var payloadProtector=protection.CreateProtector("OrcaFacil.EmailOutbox.Payload.v1");db.EmailOutboxMessages.Add(new EmailOutboxMessage{TemplateCode="password-reset",RecipientHash=emailHash,RecipientMasked=Mask(normalized),ProtectedRecipient=recipientProtector.Protect(normalized),ProtectedPayload=payloadProtector.Protect(JsonSerializer.Serialize(payload)),Priority=EmailPriority.High,CorrelationId=correlationId,IdempotencyKey=$"password-reset:{entity.Id}"});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);logger.LogInformation("PASSWORD_RESET_EMAIL_ENQUEUED CorrelationId {CorrelationId} UserId {UserId} EmailHash {EmailHash}",correlationId,user.Id,emailHash);}
 public async Task<bool> IsTokenValidAsync(string token,CancellationToken ct){if(string.IsNullOrWhiteSpace(token)||token.Length>200)return false;var hash=tokens.Hash(token);var found=await db.PasswordResetTokens.AsNoTracking().SingleOrDefaultAsync(x=>x.TokenHash==hash,ct);return found?.IsAvailable(DateTime.UtcNow)==true&&await db.Users.AnyAsync(x=>x.Id==found.UserId&&!x.IsDeleted,ct);}
 public async Task<bool> ResetAsync(string token,string password,CancellationToken ct){if(!await IsTokenValidAsync(token,ct))return false;var hash=tokens.Hash(token);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var reset=await db.PasswordResetTokens.SingleOrDefaultAsync(x=>x.TokenHash==hash,ct);if(reset?.IsAvailable(DateTime.UtcNow)!=true)return false;var user=await db.Users.SingleAsync(x=>x.Id==reset.UserId,ct);if(hasher.Verify(password,user.PasswordHash))return false;user.PasswordHash=hasher.Hash(password);user.RevokeSessions();reset.Use(DateTime.UtcNow);foreach(var old in await db.PasswordResetTokens.Where(x=>x.UserId==user.Id&&x.Id!=reset.Id&&x.UsedAt==null&&x.RevokedAt==null).ToListAsync(ct))old.Revoke(DateTime.UtcNow);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return true;}
 string Hmac(string value){using var h=new HMACSHA256(Encoding.UTF8.GetBytes(secrets.Value.SecurityEventPepper));return Convert.ToHexString(h.ComputeHash(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();}static string Mask(string e){var a=e.IndexOf('@');return a<2?"***":$"{e[0]}***{e[(a-1)..]}";}static OutboxPayload RecoveryTemplate(string link,int minutes,DateTime expires)=>new("Redefina sua senha do OrçaFácil",$"Crie uma nova senha: {link}\nO link vale por {minutes} minutos e só pode ser usado uma vez. Se você não solicitou, ignore. Suporte: comercial@mnsoft.com.br\nMNSOFT — CNPJ 18.160.057/0001-13",$"<div style=\"background:#f4f6f8;padding:32px;font-family:Arial,sans-serif;color:#172033\"><div style=\"max-width:600px;margin:auto;background:#fff\"><div style=\"background:#102a43;color:#fff;padding:24px;font-size:24px;font-weight:bold\">OrçaFácil</div><div style=\"padding:32px\"><h1>Crie uma nova senha</h1><p>Recebemos uma solicitação para redefinir sua senha.</p><p><a href=\"{System.Net.WebUtility.HtmlEncode(link)}\" style=\"display:inline-block;background:#16865b;color:#fff;padding:14px 22px;text-decoration:none;border-radius:6px\">Criar uma nova senha</a></p><p>Este link vale por {minutes} minutos e só pode ser usado uma vez.</p><p>Se você não solicitou, ignore esta mensagem.</p><p style=\"font-size:13px\">MNSOFT · CNPJ 18.160.057/0001-13 · comercial@mnsoft.com.br</p></div></div></div>",expires);
}
